import ast, json, re, html
from pathlib import Path
from html import escape
S=json.loads(Path('source.json').read_text())
R=json.loads(Path('reference-targets.json').read_text())
A={}
# Les fragments de l'ancien travail sont lus comme des données littérales,
# sans exécuter ce script, qui porte sur un autre ordre d'articles.
OLD={}
for node in ast.parse(Path('compose_answer.py').read_text()).body:
    if isinstance(node,ast.Expr) and isinstance(node.value,ast.Call) and isinstance(node.value.func,ast.Name) and node.value.func.id=='add':
        call=node.value
        vals=[ast.literal_eval(x) for x in call.args]
        kw={x.arg:ast.literal_eval(x.value) for x in call.keywords}
        OLD[vals[0]]=(vals[1:],kw)

def plain(x):
    return re.sub(r'\s+',' ',html.unescape(re.sub(r'<[^>]*>',' ',x or ''))).strip()
def xml(ps): return ''.join('<p>'+escape(p,quote=False)+'</p>' for p in ps)
def add(i,ps,reason,notes,removed=None,benefit=None):
    s=S[i]; a={k:s[k] for k in ['code_id','source_id','source_sha256','number']}
    a.update(proposed_xml=xml(ps),reason=reason,review_notes=notes,status='rewrite_draft')
    if removed: a.update(change_type='normative_reduction',reform_policy_id='editorial_direction_2026_10_19',removed_provisions=removed)
    if benefit:a['benefit_review']=benefit
    A[i]=a
    return a

def reuse(i,oi):
    vals,kw=OLD[oi]
    return add(i,*vals,**kw)

def retain(i,reason,notes,benefit=None):
    s=S[i]; a={k:s[k] for k in ['code_id','source_id','source_sha256','number']}
    a.update(proposed_xml=None,reason=reason,review_notes=notes,status='retained_unchanged')
    if benefit:a['benefit_review']=benefit
    A[i]=a

def impact(i,c,assessment,limits,burdens,effects=None):
    A[i]['substantive_impact']=dict(version=1,classification=c,assessment=assessment,scope_limitations=limits,new_burdens_review=burdens,effects=effects or [])

def effect(kind,mid,desc,before,after,unit,pop,trans,repl,sq,pq):
    return dict(kind=kind,measure_id=mid,description=desc,before=before,after=after,unit=unit,affected_population=pop,conditions_and_transition=trans,replacement_or_new_burdens=repl,source_quote=sq,proposed_quote=pq)

